/**
 * A class representing shared characteristics of animals,
 * could be initialised for prey animals.
 *
 * @version 2022.02.28
 */

public class Animal extends Species
{
    // Fields defining a special kind of animal, they can not be changed after initialization

    // The age at which an animal can start to breed.
    private final int breedingAge;
    // The age to which an animal can live.
    private final int maxAge;
    // The maximum number of births at once.
    private final int maxLitterSize;
    // true if the animal's sex if female
    private final boolean isFemale;
    // true if the animal hibernates during cold temperatures
    private final boolean hibernates;
    // true if the animal is active at night
    private final boolean isNocturnal;
    // the number of steps that should pass until an animal in hibernation moves
    private static final int STAY_STEPS = 10;

    // Fields prone to change during the animal's life

    // The animal's food level
    protected int foodLevel;
    // number of steps where the animal is in hibernation
    private int hiberSteps;
    // true if the animal is currently hibernating
    private boolean inHibernation;
    // The animal's age.
    private int age;

    /**
     * Create a new animal with given specifications. An animal can be created with random age (or start at age 0) and
     * with a random foodLevel.
     *
     * @param field (Field) the field where the simulation takes place
     * @param location (Location) the Location at which the animal should appear
     * @param name (String) the animal's name (its species' name)
     * @param maximumTemperature (int) the maximum temperature the animal can survive to
     * @param minimumTemperature (int) the minimum temperature an animal can survive to
     * @param nutritionalValue (int) the animal's nutritional value
     * @param reproductionProbability (double) the probability that the animal reproduces at each step after a given minimum breeding age
     * @param maxAge (int) the animal's life expectancy
     * @param breedingAge (int) the age at which animal can start to reproduce
     * @param maxLitterSize (int) the maximum number of children the animal can have in one reproduction
     * @param randomAge (boolean) whether an animal should be created with a random age
     * @param hibernates (boolean) whether an animal is able to hibernate
     * @param isNocturnal (boolean) whether an animal is more active at night
     */
    public Animal(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize, boolean randomAge, boolean hibernates, boolean isNocturnal)
    {
        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);

        this.breedingAge = breedingAge;
        this.maxAge = maxAge;
        this.maxLitterSize = maxLitterSize;
        this.isFemale = randomSex();
        this.hibernates = hibernates;
        this.isNocturnal = isNocturnal;
        // Default value is nutritionalValue to simulate the nutriment apart from the mother's milk/ other parental feeding.
        this.foodLevel = randomFoodLevel();
        inHibernation = false;
        hiberSteps = 0;

        if (randomAge) {
            age = rand.nextInt(maxAge);
        } else {
            age = 0;
        }
    }

    /**
     * Imitate an animal's step by doing the following:
     * 1) increment the animal's age if a year has passed.
     * 2) if the animal is alive, then:
     *      i) check if the animal should hibernate.
     *      ii) if the animal is in hibernation, then:
     *          a) if it passed STAY_STEPS steps without moving, then move and increment hunger.
     *          b) increment hiberSteps.
     *      iii) if the animal can't withstand the current temperature, then it dies.
     *      iv) if the animal is not in hibernation, then:
     *          a) if it is night and the animal is nocturnal, then move.
     *          b) if it is day, then all animals move and increment hunger.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     * @param isNight (boolean) true if it is night in the simulation
     * @param temperature (int) the current temperature of the simulation
     * @param yearPassed true if a year has passed in the simulation
     */
    public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed)
    {
        // 1)
        if (yearPassed) {
            incrementAge();
        }

        // 2)
        if(isAlive())
        {
            // i)
            checkHibernation(temperature);

            // ii)
            if (inHibernation)
            {
                // a)
                if (hiberSteps % STAY_STEPS == 0)   {
                    makeMove(newSpecies);
                    incrementHunger();
                }
                // b)
                incrementHiberSteps();
            }
            // iii)
            else if (! survivesTemperature(temperature))
            {
                setDead();
            }
            // iv)
            else
            {
                // a)
                if (isNight && isNocturnal) {
                    makeMove(newSpecies);
                }
                // b)
                else if (! isNight) {
                    makeMove(newSpecies);
                }
                if  (! isNight) {
                    incrementHunger();
                }
            }
        }
    }

    /**
     * An animal's movement. It first tries to reproduce, then to eat if a plant is in one of the neighboring cells and finally to move
     * if an adjacent cell is available. If no adjacent cell is available, it dies of overcrowding.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     */
    protected void makeMove(List<Species> newSpecies)
    {
        ArrayList<Animal> neighboringAnimalsList = getNeighboringAnimalsList();

        if (canReproduce(neighboringAnimalsList)) {
            reproduce(newSpecies);
        }

        // Eats if it is possible
        if (isNotFull()) {
            findFoodAndEat();
        }

        // Find a free location in adjacent cells
        Location newLocation = getField().freeAdjacentLocation(getLocation());

        // See if it was possible to move.
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            // Overcrowding.
            setDead();
        }
    }

    /**
     * Returns a list of animals located in neighboring cells.
     *
     * @return (ArrayList) list of neighboring animals
     */
    protected ArrayList<Animal> getNeighboringAnimalsList()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> locationIterator = adjacent.iterator();

        ArrayList<Animal> neighboringAnimals = new ArrayList<>();
        while (locationIterator.hasNext())
        {
            Location where = locationIterator.next();
            Object species = field.getObjectAt(where);

            if (species instanceof Animal) {
                Animal neighboringAnimal = (Animal) species;
                if (neighboringAnimal.isAlive()) {
                    neighboringAnimals.add(neighboringAnimal);
                }
            }
        }
        return neighboringAnimals;
    }

    /**
     * Increase the age. This could result in the animal's death.
     */
    protected void incrementAge()
    {
        age++;
        if(age > maxAge) {
            setDead();
        }
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()

import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;

/**
 * This is the main class of the simulation, as it connects all the other classes
 * and runs the simulation. In general, the classes simulate a habitat in which
 * there are preys who feed on plants, and predators who compete for the preys.
 *
 * @version 2022.02.28
 */
public class Simulator
{
    private static final int LONG_SIMULATION_STEP_COUNT = 2000;
    // List of species in the field.
    private List<Species> species;
    // The current state of the field.
    private Field field;
    // keep track of the simulation steps.
    private SimulationStep simStep;
    // A graphical view of the simulation.
    private SimulatorView view;
    // keep track of the time in the simulation
    private Time time;
    // the habitat of the simulation
    private Habitat simulationHabitat;
    private boolean simulationIsOn;

    private static final int DEFAULT_DELAY = 0;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator(Habitat simulationHabitat, Time time, List<Species> speciesInSimulation, Field field, SimulationStep simulationStepCounter, SimulatorView simulatorView)
    {
        this.simulationHabitat = simulationHabitat;
        this.time = time;
        this.species = speciesInSimulation;
        this.field = field;
        this.simStep = simulationStepCounter;
        this.view = simulatorView;
        this.simulationIsOn = true;

        view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
    }


    /**
     * Run the simulation from its current state for a reasonably long period set as a class constant.
     */
    public void runLongSimulation()
    {
        simulate(LONG_SIMULATION_STEP_COUNT);
    }

    public void runHundredSteps()
    {
        simulate(100);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     *
     * @param numSteps (int) The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            delay(DEFAULT_DELAY);
            simulateOneStep();
            // delay(200);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each specie.
     */
    public void simulateOneStep()
    {
        if (simulationIsOn) {
            simStep.incStep();
            simulationHabitat.habitatStep();
            time.timeStep();

            // the following variables are added here to reduce method calls:
            boolean isSpring = simulationHabitat.getIsSpring();
            boolean isNight = time.getIsNight();
            int currentTemperature = simulationHabitat.getCurrentTemperature();
            boolean yearPassed = simulationHabitat.yearPassed();

            // Provide space for newborn species.
            List<Species> newSpecies = new ArrayList<>();
            // Let all species act.
            for(Iterator<Species> it = species.iterator(); it.hasNext(); )
            {
                Species specie = it.next();
                // Update the status of isSpring in the plants (done here to reduce coupling)
                if (specie instanceof Plant)
                {
                    Plant tempPlant = (Plant) specie;
                    if (tempPlant.getIsSpring() != isSpring) {
                        tempPlant.toggleIsSpring();
                    }
                }

                specie.act(newSpecies, isNight, currentTemperature, yearPassed);
                if(! specie.isAlive()) {
                    it.remove();
                }
            }

            // Add the newly born species to the main lists.
            species.addAll(newSpecies);
            view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
        }
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void endSimulation()
    {
        simStep.reset();
        species.clear();
        simulationIsOn = false;
    }

    /**
     * Pause for a given time.
     * @param millisec (int) The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.util.ArrayList;

/**
 * A class to govern behavior of the various CSV Readers (one for plants, animals, scenarios, and habitats).
 * This class implements the actual "reading from a .csv file behavior" behaviour.
 *
 * @version 2022.02.28
 */
public abstract class CSVReader
{
    /**
     * Empty constructor for this class.
     */
    public CSVReader()
    {
    }

    /**
     * Method to be called by children, it centralizes the CSV Readers operations by
     * orchestrating the process of reading data from the .csv file and populating
     * the appropriate fields with the read data.
     *
     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
     */
    public void extractDataFor(String nameOfElementToLookFor)
    {
        resetParameters();
        String[] extractedData = getDataFor(nameOfElementToLookFor);
        if (extractedData != null) {
            populateFields(extractedData);
        } else {
            System.out.println("ERROR: no data could be read for " + nameOfElementToLookFor);
        }
    }

    /**
     * Reads the data relative to a given element in the appropriate .csv file
     * (the path to this file depends on the children class from which this method is called)
     * Source: technique to read .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
     *
     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
     * @return (String[]) the extracted data
     */
    private String[] getDataFor(String nameOfElementToLookFor)
    {
        try(BufferedReader br = new BufferedReader(new FileReader(getFileName()))) {
            // Skip first line as they are headers.
            String line = br.readLine();
            while ((line=br.readLine()) != null) {
                String[] attributes = line.split(",");
                if (attributes[0].equals(nameOfElementToLookFor)) {
                    return attributes;
                }
            }
        } catch (Exception e) {
            System.out.println("Issue when parsing CSV");
        }
        return null;
    }

    /**
     * Abstract method that must be overridden with the appropriate behaviours
     * needed to populate the fields of the child class.
     *
     * @param extractedData (String[]) The data extracted from the .csv file.
     */
    abstract void populateFields(String[] extractedData);

    /**
     * Abstract method used to reset all the fields of a CSV Reader object when
     * the reading is done and another element ca be expected to be read.
     */
    abstract void resetParameters();

    /**
     * Abstract method to return the name of the file containing the data to be read.
     *
     * @return (String) the file name.
     */
    abstract String getFileName();

    /**
     * Returns a list of choices (of animals, habitats, and scenarios depending
     * on the child class it is called from) available to the user.
     * Source: technique to read from .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
     *
     * @return (ArrayList<String>) The list of available choices.
     */
    public ArrayList<String> getChoicesList()
    {
        ArrayList<String> choicesList = new ArrayList<>();
        try(BufferedReader br = new BufferedReader(new FileReader(getFileName()))) {
            // Skip first line as they are headers.
            String line = br.readLine();
            while ((line=br.readLine()) != null) {
                String[] attributes = line.split(",");
                choicesList.add(attributes[0]);
            }
        } catch (Exception e) {
            e.printStackTrace();
            System.out.println("Issue when parsing CSV");
            return null;
        }
        return choicesList;
    }
}

import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;

/**
 * Represent a rectangular grid of field positions. Each position is able to store a single animal.
 *
 * @version 2022.02.28
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();

    // The depth and width of the field.
    private int depth, width;
    // Storage for the animals.
    private Object[][] field;

    /**
     * Represent a field of the given dimensions.
     *
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        field = new Object[depth][width];
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                field[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     *
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        field[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place an animal at the given location. If there is already an animal at the location it will be lost.
     *
     * @param species The animal to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(Object species, int row, int col)
    {
        place(species, new Location(row, col));
    }

    /**
     * Place an animal at the given location. If there is already an animal at the location it will be lost.
     *
     * @param species The animal to be placed.
     * @param location Where to place the animal.
     */
    public void place(Object species, Location location)
    {
        field[location.getRow()][location.getCol()] = species;
    }

    /**
     * Return the animal at the given location, if any.
     *
     * @param location Where in the field.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(Location location)
    {
        return getObjectAt(location.getRow(), location.getCol());
    }

    /**
     * Return the animal at the given location, if any.
     *
     * @param row The desired row.
     * @param col The desired column.
     * @return The animal at the given location, or null if there is none.
     */
    public Object getObjectAt(int row, int col)
    {
        return field[row][col];
    }

    /**
     * Generate a random location that is adjacent to the given location, or is the same location.
     * The returned location will be within the valid bounds of the field.
     *
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     *
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getObjectAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1; roffset <= 1; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1; coffset <= 1; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }
}

import java.util.Arrays;

/**
 * This class reads from "habitats.csv" the information about all the habitats
 * that are available to be put in the simulation.
 *
 * @version 2022.02.28
 */

public class HabitatCSVReader extends CSVReader {
    // List of minimum, average, and maximum temperatures for the winter.
    private int[] winterTemperatures;
    // List of minimum, average, and maximum temperatures for the spring.
    private int[] springTemperatures;
    // List of minimum, average, and maximum temperatures for the summer.
    private int[] summerTemperatures;
    // List of minimum, average, and maximum temperatures for the autumn.
    private int[] autumnTemperatures;
    // The concentration of plants in a given habitat.
    private double plantConcentration;
    // Tool to alert user about any potential error.
    private ErrorThrower errorThrower;

    // Name of the CSV files containing data on fields.
    private static final String FILE_NAME = "habitats.csv";

    /**
     * Build a HabitatCSVReader and initialize its fields.
     */
    public HabitatCSVReader() {
        errorThrower = new ErrorThrower();
        winterTemperatures = new int[2];
        autumnTemperatures = new int[2];
        springTemperatures = new int[2];
        summerTemperatures = new int[2];
        plantConcentration = 0;
    }

    /**
     * Populate the fields with the data extracted from the .csv file. Fields are used to store data of the right type to be easily fetched
     * by the Initializer when trying to get information about a specific habitat.
     * Habitat name from the data is removed to facilitate reading, the first 12 elements are in groups of 2 relating to each season
     * (average temperature, and maximum change to temperature ), the 13th element is the plant concentration in that habitat.
     *
     * @param extractedData (String[]) the data from the CSV file relative to a specific habitat.
     */
    protected void populateFields(String[] extractedData)
    {
        extractedData = removeHabitatName(extractedData);
        if (extractedData.length != 9) {
            errorThrower.throwMessage("Habitat issue, please restart.");
        }

        for(int i = 0; i < extractedData.length; i++) {
            if(i/2 == 0) {
                winterTemperatures[i%2] = Integer.parseInt(extractedData[i]);
            } else if (i/2 == 1) {
                springTemperatures[i%2] = Integer.parseInt(extractedData[i]);
            } else if (i/2 == 2) {
                summerTemperatures[i%2] = Integer.parseInt(extractedData[i]);
            } else if (i/2 == 3){
                autumnTemperatures[i%2] = Integer.parseInt(extractedData[i]);
            }
            plantConcentration = Double.valueOf(extractedData[8]);
        }
    }

    /**
     * Set all parameters back to initial values before reading data for another habitat.
     */
    protected void resetParameters()
    {
        winterTemperatures = new int[2];
        springTemperatures = new int[2];
        summerTemperatures = new int[2];
        autumnTemperatures = new int[2];
        plantConcentration = 0;

    }

    /**
     * Returns the list of extracted data without the habitat's name (as this informaiton is known by the Initializer and will therefore
     * not be asked). The name is the first element of the attributes list.
     *
     * @param attributes (String[]) the data from the CSV file relative to a specific habitat.
     * @return (String[]) The data without the habitat's name.
     */
    private String[] removeHabitatName(String[] attributes)
    {
        String[] attributesWithoutHabitatName = Arrays.copyOfRange(attributes,1,attributes.length);
        return attributesWithoutHabitatName;
    }

    /**
     * @return (String) The name of the file containing habitat data.
     */
    protected String getFileName() {
        return FILE_NAME;
    }

    /**
     * @return (int[]) Minimum, average, and maximum temperatures for the winter.
     */
    public int[] getWinterTemperatures()
    {
        return winterTemperatures;
    }

    /**
     * @return (int[]) Minimum, average, and maximum temperatures for the autumn.
     */
    public int[] getAutumnTemperatures() {
        return autumnTemperatures;
    }

    /**
     * @return (int[]) Minimum, average, and maximum temperatures for the spring.
     */
    public int[] getSpringTemperatures() {
        return springTemperatures;
    }

    /**
     * @return (int[]) Minimum, average, and maximum temperatures for the summer.
     */
    public int[] getSummerTemperatures() {
        return summerTemperatures;
    }

    /**
     * @return (double) The concentration of plants in the habitat.
     */
    public double getPlantConcentration() {
        return plantConcentration;
    }
}

import java.util.List;
import java.util.Random;

/**
 * This is an abstract class representing all the species of
 * the simulation. It defines some characteristics and methods
 * of the species.
 *
 * @version 2022.02.28
 */
public abstract class Species
{
    // The probability for an individual to die if exposed to too high or too cold temperatures. Can be adjusted for simulation realism purposes.
    private static final double DYING_OF_COLD_OR_HEAT_PROBABILITY = 0.8;
    // Whether the species is alive or not.
    private boolean alive;
    // The animal's field.
    private Field field;
    // The species' position in the field.
    private Location location;
    // The species' name
    private final String name;
    // The maximum temperature at which the species can survive
    private final int maximumTemperature;
    // The minimum temperature at which the species can survive
    private final int minimumTemperature;
    // The food value animal provides when eaten
    private final int nutritionalValue;
    // The likelihood of a specie to reproduce.
    private final double reproductionProbability;
    // A random number generator
    protected static final Random rand = Randomizer.getRandom();

    /**
     * Create a new specie at location in field.
     *
     * @param field (Field) The field currently occupied.
     * @param location (Location) The location within the field.
     * @param name (String) The name of the specie
     * @param maximumTemperature (int) The maximum temperature that the specie can withstand
     * @param minimumTemperature (int) The minimum temperature that the specie can withstand
     * @param nutritionalValue (int) The nutritional value given to the specie that eats this specie
     * @param reproductionProbability (double) The probability that this specie will reproduce
     */
    public Species(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability)
    {
        alive = true;
        this.field = field;
        setLocation(location);
        this.name = name;
        this.maximumTemperature = maximumTemperature;
        this.minimumTemperature = minimumTemperature;
        this.nutritionalValue = nutritionalValue;
        this.reproductionProbability = reproductionProbability;
    }

    /**
     * Make this animal act - that is: make it do whatever it wants/needs to do.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     * @param isNight (boolean) If it is currently night.
     * @param yearPassed (boolean) If a year is passing on this step (next step is the first of a nw year).
     */
    abstract public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed);

    /**
     * An abstract class to enforce all subclasses to make their elements reproduce
     *
     * @param newOfThisKind List of Species objects in the simulation for the newborns to be added to it
     */
    abstract void reproduce(List<Species> newOfThisKind);

    /**
     * Check whether the animal is alive or not.
     *
     * @return (boolean) true if the animal is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the animal is no longer alive. It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the animal's location.
     *
     * @return (Location)The animal's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the animal at the new location in the given field.
     *
     * @param newLocation (Location) The animal's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location  != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * @return (Field) The animal's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Check if animal can survive the current temperature. If temperature is too low or too high, animal has a high probability of dying
     * (probability defined as a class constant to allow easy adjusting).
     *
     * @return (Field) The animal's field.
     */
    protected boolean survivesTemperature(int temperature)
    {
        if (temperature > maximumTemperature || temperature < minimumTemperature) {
            return Math.random() <= DYING_OF_COLD_OR_HEAT_PROBABILITY;
        }
        return true;
    }

    /**
     * @return (String) The specie's name.
     */
    protected String getName()
    {
        return name;
    }

    /**
     * @return (int) The maximum temperature specie can survive to.
     */
    protected int getMaximumTemperature()
    {
        return maximumTemperature;
    }

    /**
     * @return (int) The minimum temperature specie can survive to.
     */
    protected int getMinimumTemperature()
    {
        return minimumTemperature;
    }

    /**
     * @return (int) The specie's nutritional value.
     */
    protected int getNutritionalValue()
    {
        return nutritionalValue;
    }

    /**
     * @return (double) The specie's reproduction probability.
     */
    protected double getReproductionProbability()
    {
        return reproductionProbability;
    }

}

