        maximumTemperature = Integer.valueOf(extractedData[2]);
        minimumTemperature = Integer.valueOf(extractedData[3]);
        maximumAge = Integer.valueOf(extractedData[4]);
        breedingAge = Integer.valueOf(extractedData[5]);
