        maxLitterSize = Integer.valueOf(extractedData[7]);
        nutritionalValue = Integer.valueOf(extractedData[8]);
        strength = Integer.valueOf(extractedData[9]);
        if (extractedData[10].equals(TRUE_SYMBOL)) {
            hibernates = true;
