  6	/**
  7	 * A class to govern behavior of the various CSV Readers (one for plants, animals, scenarios, and habitats).
  8	 * This class implements the actual "reading from a .csv file behavior" behaviour.
  9	 *
 10	 * @version 2022.02.28
 11	 */
 12	public abstract class CSVReader
 13	{
 14	    /**
 15	     * Empty constructor for this class.
 16	     */
 17	    public CSVReader()
 18	    {
 19	    }
 20	
 21	    /**
 22	     * Method to be called by children, it centralizes the CSV Readers operations by
 23	     * orchestrating the process of reading data from the .csv file and populating
 24	     * the appropriate fields with the read data.
 25	     *
 26	     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
 27	     */
 28	    public void extractDataFor(String nameOfElementToLookFor)
 29	    {
 30	        resetParameters();
 31	        String[] extractedData = findRowFor(nameOfElementToLookFor);
 32	        if (extractedData != null) {
 33	            populateFields(extractedData);
 34	        } else {
 35	            System.out.println("ERROR: no data could be read for " + nameOfElementToLookFor);
 36	        }
 37	    }
 38	
 39	    /**
 40	     * Reads the data relative to a given element in the appropriate .csv file
 41	     * (the path to this file depends on the children class from which this method is called)
 42	     * Source: technique to read .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
 43	     *
 44	     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
 45	     * @return (String[]) the extracted data
 46	     */
 47	    private String[] findRowFor(String nameOfElementToLookFor)
 48	    {
 49	        try (BufferedReader br = new BufferedReader(new FileReader(getFileName()))) {
 50	            // Skip first line as they are headers.
 51	            br.readLine();
 52	            String line;
 53	            while ((line = br.readLine()) != null) {
 54	                String[] attributes = line.split(",", -1);
 55	                if (attributes[0].equals(nameOfElementToLookFor)) {
 56	                    return attributes;
 57	                }
 58	            }
 59	        } catch (IOException e) {
 60	            System.out.println("Issue when parsing CSV");
 61	        }
 62	        return null;
 63	    }
 64	
 65	    /**
 66	     * Abstract method that must be overridden with the appropriate behaviours
 67	     * needed to populate the fields of the child class.
 68	     *
 69	     * @param extractedData (String[]) The data extracted from the .csv file.
 70	     */
 71	    abstract void populateFields(String[] extractedData);
 72	
 73	    /**
 74	     * Abstract method used to reset all the fields of a CSV Reader object when
 75	     * the reading is done and another element ca be expected to be read.
 76	     */
 77	    abstract void resetParameters();
 78	
 79	    /**
 80	     * Abstract method to return the name of the file containing the data to be read.
 81	     *
 82	     * @return (String) the file name.
 83	     */
 84	    abstract String getFileName();
 85	
 86	    /**
 87	     * Returns a list of choices (of animals, habitats, and scenarios depending
 88	     * on the child class it is called from) available to the user.
 89	     * Source: technique to read from .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
 90	     *
 91	     * @return (ArrayList<String>) The list of available choices.
 92	     */
 93	    public ArrayList<String> getChoicesList()
 94	    {
 95	        ArrayList<String> choicesList = new ArrayList<>();
 96	        try (BufferedReader br = new BufferedReader(new FileReader(getFileName()))) {
 97	            // Skip first line as they are headers.
 98	            br.readLine();
 99	            String line;
100	            while ((line = br.readLine()) != null) {
101	                String[] attributes = line.split(",", -1);
102	                choicesList.add(attributes[0]);
103	            }
104	        } catch (IOException e) {
105	            e.printStackTrace();
106	            System.out.println("Issue when parsing CSV");
107	            return null;
108	        }
109	        return choicesList;
110	    }
111	}

  1	import java.util.List;
  2	import java.util.ArrayList;
  3	import java.util.Iterator;
