  3	/**
  4	 * This class reads from "habitats.csv" the information about all the habitats
  5	 * that are available to be put in the simulation.
  6	 *
  7	 * @version 2022.02.28
  8	 */
  9	
 10	public class HabitatCSVReader extends CSVReader {
 11	    // List of minimum, average, and maximum temperatures for the winter.
 12	    private int[] winterTemperatures;
 13	    // List of minimum, average, and maximum temperatures for the spring.
 14	    private int[] springTemperatures;
 15	    // List of minimum, average, and maximum temperatures for the summer.
 16	    private int[] summerTemperatures;
 17	    // List of minimum, average, and maximum temperatures for the autumn.
 18	    private int[] autumnTemperatures;
 19	    // The concentration of plants in a given habitat.
 20	    private double plantConcentration;
 21	    // Tool to alert user about any potential error.
 22	    private ErrorThrower errorThrower;
 23	
 24	    // Name of the CSV files containing data on fields.
 25	    private static final String FILE_NAME = "habitats.csv";
 26	
 27	    /**
 28	     * Build a HabitatCSVReader and initialize its fields.
 29	     */
 30	    public HabitatCSVReader() {
 31	        errorThrower = new ErrorThrower();
 32	        winterTemperatures = new int[2];
 33	        autumnTemperatures = new int[2];
 34	        springTemperatures = new int[2];
 35	        summerTemperatures = new int[2];
 36	        plantConcentration = 0;
 37	    }
 38	
 39	    /**
 40	     * Populate the fields with the data extracted from the .csv file. Fields are used to store data of the right type to be easily fetched
 41	     * by the Initializer when trying to get information about a specific habitat.
 42	     * Habitat name from the data is removed to facilitate reading, the first 12 elements are in groups of 2 relating to each season
 43	     * (average temperature, and maximum change to temperature ), the 13th element is the plant concentration in that habitat.
 44	     *
 45	     * @param extractedData (String[]) the data from the CSV file relative to a specific habitat.
 46	     */
 47	    protected void populateFields(String[] extractedData)
 48	    {
 49	        extractedData = removeHabitatName(extractedData);
 50	        if (extractedData.length != 9) {
 51	            errorThrower.throwMessage("Habitat issue, please restart.");
 52	        }
 53	
 54	        for(int i = 0; i < extractedData.length; i++) {
 55	            int seasonIndex = i / 2;
 56	            int valueIndex = i % 2;
 57	            int parsedValue = Integer.parseInt(extractedData[i]);
 58	
 59	            if(seasonIndex == 0) {
 60	                winterTemperatures[valueIndex] = parsedValue;
 61	            } else if (seasonIndex == 1) {
 62	                springTemperatures[valueIndex] = parsedValue;
 63	            } else if (seasonIndex == 2) {
 64	                summerTemperatures[valueIndex] = parsedValue;
 65	            } else if (seasonIndex == 3) {
 66	                autumnTemperatures[valueIndex] = parsedValue;
 67	            }
 68	        }
 69	        plantConcentration = Double.valueOf(extractedData[8]);
 70	    }
 71	
 72	    /**
 73	     * Set all parameters back to initial values before reading data for another habitat.
 74	     */
 75	    protected void resetParameters()
 76	    {
 77	        winterTemperatures = new int[2];
 78	        springTemperatures = new int[2];
 79	        summerTemperatures = new int[2];
 80	        autumnTemperatures = new int[2];
 81	        plantConcentration = 0;
 82	
 83	    }
 84	
 85	    /**
 86	     * Returns the list of extracted data without the habitat's name (as this informaiton is known by the Initializer and will therefore
 87	     * not be asked). The name is the first element of the attributes list.
 88	     *
 89	     * @param attributes (String[]) the data from the CSV file relative to a specific habitat.
 90	     * @return (String[]) The data without the habitat's name.
 91	     */
 92	    private String[] removeHabitatName(String[] attributes)
 93	    {
 94	        String[] attributesWithoutHabitatName = Arrays.copyOfRange(attributes,1,attributes.length);
 95	        return attributesWithoutHabitatName;
 96	    }
 97	
 98	    /**
 99	     * @return (String) The name of the file containing habitat data.
100	     */
101	    protected String getFileName() {
102	        return FILE_NAME;
103	    }
104	
105	    /**
106	     * @return (int[]) Minimum, average, and maximum temperatures for the winter.
107	     */
108	    public int[] getWinterTemperatures()
109	    {
110	        return winterTemperatures;
111	    }
112	
113	    /**
114	     * @return (int[]) Minimum, average, and maximum temperatures for the autumn.
115	     */
116	    public int[] getAutumnTemperatures() {
117	        return autumnTemperatures;
118	    }
119	
120	    /**
121	     * @return (int[]) Minimum, average, and maximum temperatures for the spring.
122	     */
123	    public int[] getSpringTemperatures() {
124	        return springTemperatures;
125	    }
126	
127	    /**
128	     * @return (int[]) Minimum, average, and maximum temperatures for the summer.
129	     */
130	    public int[] getSummerTemperatures() {
131	        return summerTemperatures;
132	    }
133	
134	    /**
135	     * @return (double) The concentration of plants in the habitat.
136	     */
137	    public double getPlantConcentration() {
138	        return plantConcentration;
139	    }
140	}
